import math
from functools import reduce

# Function to compute GCD of two numbers
def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

# Function to compute LCM of two numbers
def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

# Function to compute LCM of a list of numbers
def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

# --- Case n=3 ---
n = 3
print(f"--- Case n={n} ---")
x_values_n3 = {}
# We need x_k and x_{k+1} for k=1, 2, 3, 4. This means we need x_1 to x_5.
for k in range(1, 6):
    x_values_n3[k] = list_lcm(range(k, k + n))
    print(f"x_{k} = lcm({k}, ..., {k+n-1}) = {x_values_n3[k]}")

print("\n--- Ratios for n=3 ---")
ratios_n3 = {}
for k in range(1, 5):
    ratio = x_values_n3[k+1] / x_values_n3[k]
    ratios_n3[k] = ratio
    print(f"Ratio x_{k+1}/x_k: {ratios_n3[k]}")

# Check if x_{k+1} > x_k
is_increasing_n3 = all(r > 1 for r in ratios_n3.values())
print(f"Is x_{{k+1}} > x_k for k=1..4? {is_increasing_n3}")

