import math
from functools import reduce

def lcm(a, b):
    return abs(a*b) // math.gcd(a, b)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

def calculate_x_k(k, n):
    return list_lcm(range(k, k + n))

# Test n=3 for various k
n = 3
results = {}
for k in range(1, 15):
    x_k = calculate_x_k(k, n)
    x_k_plus_1 = calculate_x_k(k+1, n)
    results[k] = (x_k, x_k_plus_1)

print(f"--- Results for n={n} ---")
for k, (xk, xk1) in results.items():
    comparison = "Strictly Increasing (>)" if xk1 > xk else ("Equal (=)" if xk1 == xk else "Decreasing (<)")
    print(f"k={k}: x_k={xk}, x_{k+1}={xk1} -> {comparison}")
